calls.schema:
z.object({
          mode: Vcs.Mode.default("git"),
          context: z.coerce.number().int().nonnegative().optional(),
          directory: z.string().optional(),
        })

z.object({
          variant: z
            .string()
            .optional()
            .meta({ description: "Serve a derived rendition of the attachment instead of the stored bytes." }),
        })

z.object({
          taskID: z.string().min(1),
          evidenceID: z.string().min(1),
          artifactName: z.enum(["source", "implementation", "side-by-side", "diff"]),
        })

z.object({
          sessionID: z
            .string()
            .optional()
            .meta({ description: "Optional root or child session id for session-effective prompt catalog view" }),
        })

z.object({
          query: z.string(),
          dirs: z.enum(["true", "false"]).optional(),
          type: z.enum(["file", "directory"]).optional(),
          limit: z.coerce.number().int().min(1).max(200).optional(),
        })

z.object({
          path: z.string(),
          content: z.string(),
          expectedRevision: File.ContentRevision,
        })

z.object({
          method: z.number(),
          inputs: z.record(z.string(), z.string()).optional(),
        })

z.object({
          method: z.number(),
          inputs: z.record(z.string(), z.string()).optional(),
        })

z.object({
          method: z.number(),
          inputs: z.record(z.string(), z.string()).optional(),
        })

z.object({
          method: z.number(),
          code: z.string().optional(),
          flowID: ProviderOAuthFlowStore.FlowID,
        })

z.object({
          api: z.string().min(1),
          apiKey: z.string().optional(),
          providerID: z.string().optional(),
        })

z.object({
            code: z.string().describe("Authorization code from OAuth callback"),
            state: z.string().describe("OAuth state parameter from OAuth callback"),
          })

z
          .object({
            directory: z.string().optional(),
            q: z.string().optional(),
            status: z.string().optional(),
            limit: z.coerce.number().optional(),
            cursor: z.coerce.number().optional(),
            cursorTaskID: z.string().optional(),
          })
          .refine((query) => (query.cursor === undefined) === (query.cursorTaskID === undefined), {
            message: "cursor and cursorTaskID must be provided together",
            path: ["cursor"],
          })

z.object({
          file: z.string().min(1),
          side: z.enum(["before", "after"]),
          offset: z.coerce.number().int().nonnegative().default(0),
          length: z.coerce.number().int().positive().max(BUILD_OBSERVATION_CONTENT_CHUNK_BYTES),
        })

z.object({
          method: z.number().meta({ description: "Auth method index" }),
          inputs: z.record(z.string(), z.string()).optional().meta({ description: "Already collected inputs" }),
        })

z.object({
          method: z.number().meta({ description: "Auth method index" }),
          inputs: z.record(z.string(), z.string()).optional().meta({ description: "Collected inputs" }),
        })

z.object({
          method: z.number().meta({ description: "Auth method index" }),
          inputs: z.record(z.string(), z.string()).optional().meta({ description: "Collected inputs" }),
        })

z.object({
          method: z.number().meta({ description: "Auth method index" }),
          code: z.string().optional().meta({ description: "OAuth authorization code" }),
          flowID: ProviderOAuthFlowStore.FlowID.meta({ description: "Exact authorization flow occurrence to finish" }),
        })

z.object({
          title: z.string().optional(),
          time: z
            .object({
              archived: z.number().nullable().optional(),
            })
            .optional(),
        })

z.object({
          providerID: z.string(),
          modelID: z.string(),
          auto: z.boolean().optional().default(false),
          focus: z.string().optional(),
        })

z.object({
          sessionID: z.string().meta({ description: "Session ID" }),
          messageID: z.string().meta({ description: "Message ID" }),
        })

z.object({
          sessionID: z.string().meta({ description: "Session ID" }),
          messageID: z.string().meta({ description: "Message ID" }),
          partID: z.string().meta({ description: "Part ID" }),
        })

z.object({
          sessionID: z.string().meta({ description: "Session ID" }),
          messageID: z.string().meta({ description: "Message ID" }),
        })

z.object({
          sessionID: z.string().meta({ description: "Session ID" }),
          messageID: z.string().meta({ description: "Message ID" }),
          partID: z.string().meta({ description: "Part ID" }),
        })

z.object({
          sessionID: z.string().meta({ description: "Session ID" }),
          messageID: z.string().meta({ description: "Message ID" }),
          partID: z.string().meta({ description: "Part ID" }),
        })
